/*Table structure for table `bookings` */

DROP TABLE IF EXISTS `bookings`;

CREATE TABLE `bookings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `room_id` int(11) NOT NULL,
  `booking_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'per_night',
  `check_in` datetime NOT NULL,
  `check_out` datetime NOT NULL,
  `check_in_time` time DEFAULT NULL,
  `duration_hours` tinyint(3) unsigned DEFAULT NULL,
  `status` enum('pending_payment','pending_approval','confirmed','checked_in','checked_out','cancelled','rejected','requested','pending','no_show') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_payment',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `rejected_by` int(11) DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `payment_deadline` datetime DEFAULT NULL,
  `auto_cancelled` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `cancellation_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `no_show_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `no_show_at` datetime DEFAULT NULL,
  `no_show_waived_by` int(11) DEFAULT NULL,
  `no_show_waiver_reason` text COLLATE utf8mb4_unicode_ci,
  `is_arrived` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_booking_creator` (`created_by`),
  KEY `idx_bookings_customer` (`customer_id`),
  KEY `idx_bookings_room` (`room_id`),
  KEY `idx_bookings_dates` (`check_in`,`check_out`),
  KEY `idx_bookings_type` (`booking_type`),
  CONSTRAINT `fk_booking_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_booking_customer` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_booking_room` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=122 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

