/*Table structure for table `lost_and_found` */

DROP TABLE IF EXISTS `lost_and_found`;

CREATE TABLE `lost_and_found` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item_name` varchar(255) NOT NULL,
  `description` text,
  `found_location` varchar(255) NOT NULL,
  `found_date` date NOT NULL,
  `status` enum('Found','Claimed','Discarded') DEFAULT 'Found',
  `image_url` varchar(500) DEFAULT NULL,
  `logged_by` int(11) DEFAULT NULL,
  `claimed_by_name` varchar(255) DEFAULT NULL,
  `claimed_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `logged_by` (`logged_by`),
  CONSTRAINT `lost_and_found_ibfk_1` FOREIGN KEY (`logged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

