/*Table structure for table `motor_rentals` */

DROP TABLE IF EXISTS `motor_rentals`;

CREATE TABLE `motor_rentals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rental_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_id` int(11) DEFAULT NULL,
  `motor_id` int(11) NOT NULL,
  `start_datetime` datetime NOT NULL,
  `expected_return_datetime` datetime NOT NULL,
  `actual_return_datetime` datetime DEFAULT NULL,
  `duration` decimal(10,2) NOT NULL,
  `rate` decimal(10,2) NOT NULL,
  `rate_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily',
  `total_amount` decimal(10,2) NOT NULL,
  `late_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `hours_late` int(11) NOT NULL DEFAULT '0',
  `hourly_late_rate` decimal(10,2) NOT NULL DEFAULT '0.00',
  `late_fee_waived` tinyint(1) NOT NULL DEFAULT '0',
  `late_fee_waiver_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `final_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `status` enum('PENDING_PAYMENT','PENDING_APPROVAL','PENDING','RESERVED','ACTIVE','COMPLETED','CANCELLED','OVERDUE','REJECTED','NO_SHOW') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_PAYMENT',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `rejected_by` int(11) DEFAULT NULL,
  `rejected_at` datetime DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `payment_deadline` datetime DEFAULT NULL,
  `auto_cancelled` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int(11) DEFAULT NULL,
  `returned_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `no_show_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `no_show_at` datetime DEFAULT NULL,
  `no_show_waived_by` int(11) DEFAULT NULL,
  `no_show_waiver_reason` text COLLATE utf8mb4_unicode_ci,
  `driver_license_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver_license_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_verified_by` int(11) DEFAULT NULL,
  `license_verified_staff_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_verified_at` datetime DEFAULT NULL,
  `license_verification_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNVERIFIED',
  `license_flag_reason` text COLLATE utf8mb4_unicode_ci,
  `driver_license_restrictions` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designated_driver_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `license_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PH',
  `passport_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country_of_issuance` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foreign_license_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foreign_license_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_expiry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idp_category_a` tinyint(1) NOT NULL DEFAULT '0',
  `pickup_checklist` json DEFAULT NULL,
  `pickup_photos` json DEFAULT NULL,
  `pickup_inspected_by` int(11) DEFAULT NULL,
  `pickup_inspected_at` datetime DEFAULT NULL,
  `has_damage` tinyint(1) NOT NULL DEFAULT '0',
  `damage_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `damage_fee_waived` tinyint(1) NOT NULL DEFAULT '0',
  `damage_fee_waiver_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `return_checklist` json DEFAULT NULL,
  `return_photos` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rental_id` (`rental_id`),
  KEY `fk_mr_customer` (`customer_id`),
  KEY `fk_mr_motor` (`motor_id`),
  KEY `fk_mr_createdby` (`created_by`),
  KEY `fk_mr_returnedby` (`returned_by`),
  KEY `idx_mr_status` (`status`),
  KEY `idx_mr_dates` (`start_datetime`,`expected_return_datetime`),
  CONSTRAINT `fk_mr_createdby` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_mr_customer` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_mr_motor` FOREIGN KEY (`motor_id`) REFERENCES `motorcycles` (`id`),
  CONSTRAINT `fk_mr_returnedby` FOREIGN KEY (`returned_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `motor_rentals` */

