/*Table structure for table `request_audit_logs` */

DROP TABLE IF EXISTS `request_audit_logs`;

CREATE TABLE `request_audit_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `entity_type` enum('booking','motor_rental','activity_rental') COLLATE utf8mb4_unicode_ci NOT NULL,
  `entity_id` int(11) NOT NULL,
  `from_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `performed_by` int(11) DEFAULT NULL,
  `performed_by_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trigger_type` enum('manual','system','payment') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `reason` text COLLATE utf8mb4_unicode_ci,
  `metadata` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
