/*Table structure for table `reviews` */

DROP TABLE IF EXISTS `reviews`;

CREATE TABLE `reviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `rating` int(11) NOT NULL,
  `comment` text,
  `is_published` tinyint(1) DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `reviews_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=latin1;

/*Data for the table `reviews` */

insert  into `reviews`(`id`,`customer_id`,`rating`,`comment`,`is_published`,`created_at`) values (1,8,5,'Nice Stay',1,'2026-09-18 09:55:25'),(2,18,1,'bati kaayo',1,'2026-10-19 13:13:08'),(3,8,5,'Nice stay here',1,'2026-10-19 13:23:12'),(4,18,5,'Nice Room',1,'2026-10-19 13:24:13'),(5,17,5,'Nice Nice',1,'2026-10-19 13:24:53');

/*Table structure for table `rooms` */

DROP TABLE IF EXISTS `rooms`;

CREATE TABLE `rooms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `room_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `room_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `capacity` int(11) NOT NULL DEFAULT '1',
  `rate_per_night` decimal(10,2) NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'available',
  `description` text COLLATE utf8mb4_unicode_ci,
  `image_urls` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `room_number` (`room_number`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `rooms` */

insert  into `rooms`(`id`,`room_number`,`room_type`,`capacity`,`rate_per_night`,`status`,`description`,`image_urls`,`created_at`,`updated_at`) values (1,'101','Room',8,'1000.00','available','A breezy 8-bed mixed dorm featuring our signature hammock-style bunks. Includes personal lockers and shared bathroom access.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-10-19 00:42:34'),(2,'102','Room',6,'800.00','available','A comfortable 6-bed female-only dorm. Features privacy curtains, reading lights, and air conditioning.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-10-19 00:41:06'),(3,'201','Room',2,'900.00','available','A cozy private room with a double bed, private en-suite bathroom, and a small balcony overlooking the garden.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-10-04 23:26:21'),(4,'202','Hammock Suite',2,'1200.00','available','Our premium suite featuring a king-sized bed, an indoor lounge hammock, air conditioning, and a private sea-view balcony.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-09-24 15:31:13'),(5,'203','Family Room',4,'950.00','available','Spacious family room equipped with two queen beds, a mini-fridge, and a large private bathroom. Currently undergoing upgrades.','[\"data:image/jpeg;base64,\"]','2026-08-05 11:02:57','2026-10-11 22:01:56');
insert  into `rooms`(`id`,`room_number`,`room_type`,`capacity`,`rate_per_night`,`status`,`description`,`image_urls`,`created_at`,`updated_at`) values (6,'205','Family Room',8,'1500.00','available','Standard Queen located on Floor 1. Features 2 Queen Beds.','[\"data:image/jpeg;base64,\"]','2026-09-16 15:12:47','2026-10-11 22:36:55');

/*Table structure for table `services` */

DROP TABLE IF EXISTS `services`;

CREATE TABLE `services` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) DEFAULT NULL,
  `icon_url` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `services` */

insert  into `services`(`id`,`name`,`description`,`price`,`icon_url`,`is_active`,`created_at`,`updated_at`) values (1,'High-Speed Wi-Fi','Fast and reliable Starlink internet access available throughout the hostel property.',NULL,'????',1,'2026-08-05 11:02:57','2026-08-05 11:02:57'),(2,'Beach Towel Rental','Large, plush microfiber beach towels for your island hopping adventures.','50.00','????️',1,'2026-08-05 11:02:57','2026-08-05 11:02:57'),(3,'Laundry Service','Wash, dry, and fold service. Price is per kilogram. Delivered next day.','80.00','????',1,'2026-08-05 11:02:57','2026-08-05 11:02:57'),(4,'Airport / Seaport Transfer','Private van transfer from Tagbilaran Airport or Pier directly to the hostel.','800.00','????',1,'2026-08-05 11:02:57','2026-08-05 11:02:57'),(5,'Luggage Storage','Secure storage for your bags before check-in or after check-out.',NULL,'????',1,'2026-08-05 11:02:57','2026-08-05 11:02:57');

/*Table structure for table `users` */

DROP TABLE IF EXISTS `users`;

CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `unique_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('customer','staff','admin') COLLATE utf8mb4_unicode_ci NOT NULL,
  `full_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `middle_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `dob` date DEFAULT NULL,
  `gender` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `civil_status` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `must_change_password` tinyint(1) NOT NULL DEFAULT '1',
  `default_password` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'user123',
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `valid_id_path` text COLLATE utf8mb4_unicode_ci,
  `created_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `profile_photo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_id` (`unique_id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `username` (`username`),
  KEY `fk_users_creator` (`created_by`),
  KEY `idx_users_unique_id` (`unique_id`),
  KEY `idx_users_email` (`email`),
  KEY `idx_users_status` (`status`),
  KEY `idx_users_role` (`role`),
  CONSTRAINT `fk_users_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

