/* Procedure structure for procedure `sp_get_expenses` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_expenses` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`bhh`@`localhost` PROCEDURE `sp_get_expenses`(
        IN p_start_date DATE,
        IN p_end_date DATE
      )
BEGIN
        SELECT 
          e.id, e.amount, e.category, e.description, e.expense_date, e.created_at,
          u.full_name as logged_by_name
        FROM expenses e
        LEFT JOIN users u ON u.id = e.logged_by
        WHERE (p_start_date IS NULL OR e.expense_date >= p_start_date)
